"""Full video, step 1b (comparison set): the same keyframes generated by Z-Image Turbo in ComfyUI on Vast workers.

Same storyboard text and sizes as the Codex set, but no reference images (Z-Image is text-to-image only), so the
character has to come from the text description alone.

Usage: uv run python scripts/full_keys_comfy.py <full_dir> <comfy_url> [<comfy_url> ...]
         [--shots s01,s02] [--orient landscape|portrait]
"""

from __future__ import annotations

import io
import json
import queue
import sys
import threading
import time
from pathlib import Path

from PIL import Image

from sunomv.comfy.client import ComfyClient
from sunomv.comfy.graphs import ZIMAGE_CUDA, zimage
from sunomv.shards import split_args, wanted

SIZE = {"landscape": (1536, 1024), "portrait": (1024, 1536)}
FRAMING = {
    "landscape": "Cinematic horizontal composition, the main subject and action in the central area.",
    "portrait": "Vertical composition, the main subject centered and filling the frame.",
}


def main() -> None:
    pos, opts = split_args(sys.argv[1:])
    full, urls = Path(pos[0]), pos[1:]
    only, orients = wanted(opts)
    sb = json.loads((full / "storyboard.json").read_text())
    out_dir = full / "comfy" / "keys"
    out_dir.mkdir(parents=True, exist_ok=True)
    jobs: queue.Queue = queue.Queue()
    for i, shot in enumerate(sb["shots"]):
        if only and shot["id"] not in only:
            continue
        who = f" The woman is {sb['heroine']}." if "woman" in shot["scene"] else ""
        for orientation in orients:
            out = out_dir / f"{shot['id']}_{orientation}.png"
            if not out.exists():
                prompt = f"{shot['scene']}{who} {FRAMING[orientation]} Style: {sb['style']}."
                jobs.put((out, prompt, orientation, 1000 + i))
    total, started, lock = jobs.qsize(), time.monotonic(), threading.Lock()
    report: dict[str, float] = {}

    def worker(url: str) -> None:
        client = ComfyClient(url)
        while True:
            try:
                out, prompt, orientation, seed = jobs.get_nowait()
            except queue.Empty:
                return
            w, h = SIZE[orientation]
            r = client.run(zimage(prompt, seed=seed, width=w, height=h, m=ZIMAGE_CUDA, prefix=f"sunomv/keys/{out.stem}"))
            Image.open(io.BytesIO(r.images[0])).convert("RGB").save(out)
            with lock:
                report[out.name] = round(r.seconds, 1)
                print(f"[{len(report)}/{total}] {out.name} {r.seconds:.1f}s on {url}", flush=True)

    threads = [threading.Thread(target=worker, args=(u,)) for u in urls]
    for t in threads:
        t.start()
    for t in threads:
        t.join()
    (full / "comfy" / "keys_report.json").write_text(json.dumps(report, indent=1))
    print(f"done {len(report)}/{total} in {time.monotonic() - started:.0f}s", flush=True)


if __name__ == "__main__":
    main()
